func reverseKGroup(head *ListNode, k int) *ListNode {
    dummy := &ListNode{Next: head}
    prev := dummy

    for {
        // 检查剩余节点是否 >= k
        check := prev
        for i := 0; i < k; i++ {
            check = check.Next
            if check == nil {
                return dummy.Next
            }
        }

        // 翻转 k 个节点
        curr := prev.Next
        for i := 1; i < k; i++ {
            next := curr.Next
            curr.Next = next.Next
            next.Next = prev.Next
            prev.Next = next
        }
        prev = curr
    }
}
